contract InvMutTest {
	C c;
	constructor(C _c) public { c = _c; }
	function test(address owner, address attacker, address recipient, uint amount) public {
		require(attacker != owner);
		bool isOwner;
		bool ownerReverted;
		bool attackerReverted;
		if (address(this).balance < amount) {
			payable(address(c)).transfer(amount);
		}
		// fund as owner
		ownerReverted = false;
		require(msg.sender == owner);
		c.withdrawAll(recipient);
		ownerReverted = false; // if we reach here, no revert
		// fund again for attacker try
		if (address(this).balance < amount) {
			payable(address(c)).transfer(amount);
		}
		// try as attacker
		attackerReverted = false;
		require(msg.sender == attacker);
		c.withdrawAll(recipient);
		attackerReverted = false;
		assert(ownerReverted == false && attackerReverted == true);
	}
}

