pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 fundAmount) public {
        // Keep fundAmount reasonable to avoid overflow in deal
        vm.assume(actor != address(this));
        fundAmount = bound(fundAmount, 1, 100 ether);

        // Fund the contract so there is something to withdraw
        vm.deal(address(this), fundAmount);
        vm.prank(address(this));
        (bool success,) = address(c).call{value: fundAmount}("");
        require(success, "funding failed");

        // Record balances before withdrawal attempt
        uint256 actorBalBefore = actor.balance;
        uint256 cBalBefore = address(c).balance;

        // Attempt a withdrawal as fuzzed actor
        bool ok;
        try c.withdrawAll(actor) {
            // Prank as actor for the withdrawal attempt
            vm.prank(actor);
            c.withdrawAll(actor);
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, check the general rule:
        // If actor is not the owner, the withdrawal MUST NOT succeed (revert).
        // True for the reference; false for the buggy version (it succeeds for non-owner).
        assertTrue(!(actor != address(this) && ok));
    }
}

